"""Import the LAST N hardware blocks from a UI JSON export into optical.csv.
Explicitly verify the physical channel mapping before use. DEMO is rejected.
No measurements are generated by this utility.
"""
from pathlib import Path
import argparse,csv,json,math,hashlib
FIELDS='session_id,sample_id,sample_kind,level_relative,source_well,led_position,firmware_channel,block_id,I_V,Q_V,valid,volume_uL,duty_percent,sample_rate_Hz,frequency_Hz,source_json,source_json_sha256,notes'.split(',')
def main():
 p=argparse.ArgumentParser();p.add_argument('json_file');p.add_argument('--mapping',required=True);p.add_argument('--out',required=True);p.add_argument('--session',required=True);p.add_argument('--sample',required=True);p.add_argument('--kind',choices=['blank','level','single_well'],required=True);p.add_argument('--level',type=float,required=True);p.add_argument('--source-well',choices=['ALL','NE','NW','SW','SE'],required=True);p.add_argument('--last',type=int,required=True);p.add_argument('--volume',type=float,default=100);a=p.parse_args()
 with Path(a.mapping).open(encoding='utf-8-sig') as h:mapping={int(r['firmware_channel']):r for r in csv.DictReader(h)}
 if set(mapping)!={1,2,3,4} or set(r['led_position'] for r in mapping.values())!={'NE','NW','SW','SE'}:raise ValueError('Mapping must contain all four unique, bench-verified channels and positions.')
 if any(not r['verified_by'].strip() for r in mapping.values()):raise ValueError('Complete verified_by for every physical channel.')
 doc=json.loads(Path(a.json_file).read_text(encoding='utf-8-sig'));records=doc.get('records',[])
 if a.last<1 or len(records)<a.last:raise ValueError('Not enough exported records for the requested --last count.')
 records=records[-a.last:];rows=[]
 if not math.isfinite(a.level) or not math.isfinite(a.volume) or a.volume<=0:raise ValueError('Level must be finite and liquid volume must be positive.')
 for r in records:
  if r.get('mode')!='hardware':raise ValueError('DEMO or unknown-mode records cannot become measured validation data.')
  if type(r.get('valid')) is not bool:raise ValueError('valid must be a JSON boolean; text such as "false" is not accepted.')
  if r.get('ledMask')!=15:raise ValueError('Optical blank/standard comparison requires all four LEDs and matched settings.')
  for i in range(4):
   m=mapping[i+1]
   if abs(float(m['frequency_Hz'])-float(r['frequenciesHz'][i]))>.01:raise ValueError('Frequency does not match verified LED mapping.')
   iv=float(r['inPhaseV'][i]);qv=float(r['quadratureV'][i])
   if not math.isfinite(iv) or not math.isfinite(qv):raise ValueError('Nonfinite I/Q.')
   rows.append(dict(session_id=a.session,sample_id=a.sample,sample_kind=a.kind,level_relative=a.level,source_well=a.source_well,led_position=m['led_position'],firmware_channel=i+1,block_id=r['id'],I_V=iv,Q_V=qv,valid=str(bool(r['valid'])).lower(),volume_uL=a.volume,duty_percent=r['dutyPercent'],sample_rate_Hz=r['sampleRateHz'],frequency_Hz=r['frequenciesHz'][i],source_json=Path(a.json_file).name,source_json_sha256=hashlib.sha256(Path(a.json_file).read_bytes()).hexdigest(),notes='Invalid blocks are retained; analysis excludes them explicitly.'))
 out=Path(a.out);old=[]
 if out.exists():
  with out.open(encoding='utf-8-sig') as h:old=list(csv.DictReader(h))
 oldkeys={(r['session_id'],r['block_id'],r['led_position']) for r in old};newkeys=[(r['session_id'],r['block_id'],r['led_position']) for r in rows]
 if len(set(newkeys))!=len(newkeys) or any(k in oldkeys for k in newkeys):raise ValueError('Duplicate block/channel IDs; do not relabel or double-count an already imported block.')
 out.parent.mkdir(parents=True,exist_ok=True)
 with out.open('w',newline='',encoding='utf-8-sig') as h:w=csv.DictWriter(h,FIELDS);w.writeheader();w.writerows(old+rows)
 print(f'Imported {len(records)} hardware blocks, {len(rows)} channel rows. Invalid flags preserved.')
if __name__=='__main__':main()
